#include <format>
#include <iostream>

// Heading change of a differential-drive robot from the distance each wheel rolled.
[[nodiscard]] double heading_change_rad(double left_m, double right_m, double base_m) {
  return (right_m - left_m) / base_m;
}

int main() {
  std::cout << std::format("{:.4f} rad\n", heading_change_rad(0.10, 0.20, 0.160));
  // The new controller keeps the wheel base in millimetres.
  std::cout << std::format("{:.4f} rad\n", heading_change_rad(0.10, 0.20, 160.0));
  // This caller reads the wheels in the other order.
  std::cout << std::format("{:.4f} rad\n", heading_change_rad(0.20, 0.10, 0.160));
}

#include <cmath>

struct Metres {
  constexpr explicit Metres(double v) : value(v) {}
  double value;
};

struct OdomFrame {};
struct MapFrame {};

// A position tagged with the frame it is expressed in. The tag costs nothing at run time.
template <typename Frame>
struct Position {
  Metres x;
  Metres y;
};

[[nodiscard]] Metres distance(Position<MapFrame> a, Position<MapFrame> b) {
  return Metres{std::hypot(a.x.value - b.x.value, a.y.value - b.y.value)};
}

int main() {
  const Position<OdomFrame> robot{.x = Metres{1.0}, .y = Metres{2.0}};
  const Position<MapFrame> goal{.x = Metres{4.0}, .y = Metres{6.0}};
  return distance(robot, goal).value > 5.0 ? 1 : 0;  // the robot position is in odom, not in map
}

#include <array>
#include <charconv>
#include <cstdint>
#include <format>
#include <iostream>
#include <limits>
#include <ranges>
#include <string>
#include <string_view>
#include <system_error>
#include <variant>

struct Ticks {
  std::int64_t count;
};

struct WheelTicks {
  Ticks left;
  Ticks right;
};

struct EncoderLine {
  std::int64_t stamp_ns;
  WheelTicks ticks;
};

enum class LineError { field_count, not_a_number, out_of_range, negative_stamp };

[[nodiscard]] constexpr std::string_view name_of(LineError error) {
  switch (error) {
    case LineError::field_count: return "field_count";
    case LineError::not_a_number: return "not_a_number";
    case LineError::out_of_range: return "out_of_range";
    case LineError::negative_stamp: return "negative_stamp";
  }
  return "not a LineError";
}

// Parses "stamp_ns,left_ticks,right_ticks".
// Pre:    none. Any text is a valid argument, because the text comes from a file.
// Post:   on success, stamp_ns >= 0 and each field equals the decimal number in the line.
// Errors: the first problem found, as a LineError. Never throws, never reads outside the view.
[[nodiscard]] std::variant<EncoderLine, LineError> parse_line(std::string_view line) noexcept {
  std::array<std::int64_t, 3> fields{};
  std::ptrdiff_t count = 0;
  for (const auto part : std::views::split(line, ',')) {
    if (count == std::ssize(fields)) return LineError::field_count;
    const std::string_view text(part.begin(), part.end());
    const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), fields[count]);
    if (error == std::errc::result_out_of_range) return LineError::out_of_range;
    if (error != std::errc{} || end != text.data() + text.size()) return LineError::not_a_number;
    ++count;
  }
  if (count != std::ssize(fields)) return LineError::field_count;
  if (fields[0] < 0) return LineError::negative_stamp;
  return EncoderLine{.stamp_ns = fields[0], .ticks = {.left = Ticks{fields[1]}, .right = Ticks{fields[2]}}};
}

[[nodiscard]] std::string describe(const std::variant<EncoderLine, LineError>& result) {
  if (const auto* error = std::get_if<LineError>(&result)) return std::string(name_of(*error));
  const auto& [stamp_ns, ticks] = std::get<EncoderLine>(result);
  return std::format("{} {} {}", stamp_ns, ticks.left.count, ticks.right.count);
}

struct Case {
  std::string_view line;
  std::string_view expected;
};

int main() {
  // One case per clause of the contract.
  constexpr std::array cases{
      Case{.line = "1726650000000000000,1200,1187", .expected = "1726650000000000000 1200 1187"},
      Case{.line = "1726650000000000000,-40,-38", .expected = "1726650000000000000 -40 -38"},
      Case{.line = "", .expected = "field_count"},
      Case{.line = "1726650000000000000,1200", .expected = "field_count"},
      Case{.line = "1726650000000000000,1200,1187,5", .expected = "field_count"},
      Case{.line = "1726650000000000000,12x0,1187", .expected = "not_a_number"},
      Case{.line = "1726650000000000000, 1200,1187", .expected = "not_a_number"},
      Case{.line = "99999999999999999999,1200,1187", .expected = "out_of_range"},
      Case{.line = "-5,1200,1187", .expected = "negative_stamp"},
  };
  for (const auto& [line, expected] : cases) {
    const std::string got = describe(parse_line(line));
    std::cout << std::format("{:<35}{:<31}{}\n", std::format("\"{}\"", line), got, got == expected ? "ok" : "WRONG");
  }

  // The postcondition as a round trip: a line written from values parses back to the same values.
  constexpr std::array<std::int64_t, 5> values{0, 1, -1, std::numeric_limits<std::int64_t>::min(),
                                               std::numeric_limits<std::int64_t>::max()};
  std::int32_t lines = 0;
  std::int32_t mismatches = 0;
  for (const auto stamp : values | std::views::filter([](std::int64_t v) { return v >= 0; })) {
    for (const auto left : values) {
      for (const auto right : values) {
        const auto parsed = parse_line(std::format("{},{},{}", stamp, left, right));
        const auto* got = std::get_if<EncoderLine>(&parsed);
        const bool same = got != nullptr && got->stamp_ns == stamp && got->ticks.left.count == left &&
                          got->ticks.right.count == right;
        ++lines;
        mismatches += same ? 0 : 1;
      }
    }
  }
  std::cout << std::format("round trip: {} lines, {} mismatches\n", lines, mismatches);
}

