struct Ticks {
  std::int64_t count;
};

struct WheelTicks {
  Ticks left;
  Ticks right;
};

struct EncoderLine {
  std::int64_t stamp_ns;
  WheelTicks ticks;
};

enum class LineError { field_count, not_a_number, out_of_range, negative_stamp };

// Parser: the worked example's parse_line, with the same contract.
[[nodiscard]] std::variant<EncoderLine, LineError> parse_line(std::string_view line) noexcept {
  std::array<std::int64_t, 3> fields{};
  std::ptrdiff_t count = 0;
  for (const auto part : std::views::split(line, ',')) {
    if (count == std::ssize(fields)) return LineError::field_count;
    const std::string_view text(part.begin(), part.end());
    const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), fields[count]);
    if (error == std::errc::result_out_of_range) return LineError::out_of_range;
    if (error != std::errc{} || end != text.data() + text.size()) return LineError::not_a_number;
    ++count;
  }
  if (count != std::ssize(fields)) return LineError::field_count;
  if (fields[0] < 0) return LineError::negative_stamp;
  return EncoderLine{.stamp_ns = fields[0], .ticks = {.left = Ticks{fields[1]}, .right = Ticks{fields[2]}}};
}

// Reader.
// Post:   the next line without its newline, or nullopt at the end of the input. The view borrows
//         the reader's buffer and is valid until the next call to next().
// Errors: a failed read, as opposed to the end of the input, throws std::runtime_error.
class LineReader {
 public:
  explicit LineReader(std::istream& in) : in_(in) {}

  [[nodiscard]] std::optional<std::string_view> next() {
    if (std::getline(in_, line_)) return line_;
    if (in_.bad()) throw std::runtime_error("read failed");
    return std::nullopt;
  }

 private:
  std::istream& in_;
  std::string line_;
};

struct Wheels {
  double metres_per_tick;
  double base_m;
};

struct Motion {
  std::int64_t stamp_ns;
  double distance_m;
  double heading_change_rad;
};

enum class Skip { first_sample, stamp_not_after_last };

// Processor: the motion between consecutive samples.
// Invariant: the stamps of accepted samples strictly increase.
// Post:      a Motion covers the interval from the last accepted sample to this one.
// Errors:    the constructor throws std::invalid_argument for wheels that aren't positive. A sample
//            that isn't later than the last accepted one is refused with a Skip and changes nothing.
class Odometer {
 public:
  explicit Odometer(Wheels wheels) : wheels_(wheels) {
    if (!(wheels.metres_per_tick > 0.0 && wheels.base_m > 0.0)) throw std::invalid_argument("wheels must be positive");
  }

  [[nodiscard]] std::variant<Motion, Skip> add(const EncoderLine& sample) {
    if (last_ && sample.stamp_ns <= last_->stamp_ns) return Skip::stamp_not_after_last;
    const auto previous = std::exchange(last_, sample);
    if (!previous) return Skip::first_sample;
    const double left_m = metres(sample.ticks.left.count - previous->ticks.left.count);
    const double right_m = metres(sample.ticks.right.count - previous->ticks.right.count);
    return Motion{.stamp_ns = sample.stamp_ns,
                  .distance_m = (left_m + right_m) / 2.0,
                  .heading_change_rad = (right_m - left_m) / wheels_.base_m};
  }

 private:
  [[nodiscard]] double metres(std::int64_t ticks) const { return static_cast<double>(ticks) * wheels_.metres_per_tick; }

  Wheels wheels_;
  std::optional<EncoderLine> last_;
};

// Writer.
// Post:   one line "stamp_ns,distance_m,heading_change_rad" per call, in call order.
// Errors: a failed write throws std::runtime_error: the run can't do its job without its output.
class MotionWriter {
 public:
  explicit MotionWriter(std::ostream& out) : out_(out) {}

  void write(const Motion& motion) {
    out_ << std::format("{},{:.4f},{:.4f}\n", motion.stamp_ns, motion.distance_m, motion.heading_change_rad);
    if (!out_) throw std::runtime_error("write failed");
  }

 private:
  std::ostream& out_;
};

struct Report {
  std::int32_t lines = 0;
  std::int32_t written = 0;
  std::int32_t bad_lines = 0;
  std::int32_t out_of_order = 0;
};

// Bad lines and out-of-order samples are skipped and counted; read and write failures propagate.
[[nodiscard]] Report convert(LineReader& reader, Odometer& odometer, MotionWriter& writer) {
  Report report;
  while (const auto line = reader.next()) {
    ++report.lines;
    const auto parsed = parse_line(*line);
    const auto* sample = std::get_if<EncoderLine>(&parsed);
    if (sample == nullptr) {
      ++report.bad_lines;
      continue;
    }
    const auto step = odometer.add(*sample);
    if (const auto* motion = std::get_if<Motion>(&step)) {
      writer.write(*motion);
      ++report.written;
    } else if (std::get<Skip>(step) == Skip::stamp_not_after_last) {
      ++report.out_of_order;
    }
  }
  return report;
}

int main() {
  std::istringstream log(
      "1000000000,0,0\n"
      "1100000000,100,100\n"
      "1200000000,200,210\n"
      "1150000000,250,260\n"  // stamp goes back
      "1300000000,300,320\n"
      "1400000000,40");       // the last line of a run that crashed mid-write
  std::ostringstream out;
  LineReader reader(log);
  Odometer odometer(Wheels{.metres_per_tick = 0.0005, .base_m = 0.15});
  MotionWriter writer(out);

  const Report report = convert(reader, odometer, writer);
  std::cout << out.str();
  std::cout << std::format("lines {}, written {}, bad lines {}, out of order {}\n", report.lines, report.written,
                           report.bad_lines, report.out_of_order);
}

#include <charconv>
#include <cstdint>
#include <format>
#include <iostream>
#include <string_view>
#include <system_error>

// The C style: returns 0 on success and -1 on failure, and writes the value through a pointer.
int parse_ticks(std::string_view text, std::int64_t* out) {
  const auto [end, error] = std::from_chars(text.data(), text.data() + text.size(), *out);
  return error == std::errc{} && end == text.data() + text.size() ? 0 : -1;
}

int main() {
  std::int64_t left = 0;
  parse_ticks("12x0", &left);  // returns -1, and nobody looks
  std::cout << std::format("left wheel moved {} ticks\n", left);
}

#include <cstdint>

enum class [[nodiscard]] WriteStatus { ok, disk_full };

WriteStatus append_line(std::int64_t stamp_ns) { return stamp_ns >= 0 ? WriteStatus::ok : WriteStatus::disk_full; }

int main() {
  append_line(1726650000000000000);  // the disk may be full, and nobody looks
}
